// server.mjs — تطبيق عروض أسعار عربي (RTL) بخادم Node بوحدات مدمجة فقط
// الوحدات المستخدمة: http, fs, path (لا اعتماد خارجي)
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = 3000;
const HOST = '0.0.0.0';

// حدود التحقق
const MAX_ITEMS = 100;
const MAX_UNIT_PRICE_CENTS = 10000000;   // 0 .. 10,000,000
const MAX_QUANTITY = 10000;              // 1 .. 10,000
const MAX_DISCOUNT_PERCENT = 100;        // 0 .. 100
const MAX_SHIPPING_CENTS = 1000000;      // 0 .. 1,000,000
const MAX_SUBTOTAL_CENTS = 1000000000;   // مجموع الأسعار قبل الخصم

const INVALID = { error: 'invalid' };

// ---------- أدوات التحقق الصارم (بدون تحويل النصوص أو null إلى أرقام) ----------

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// عدد صحيح آمن ضمن نطاق [min, max] — يرفض النصوص وnull وغير الأعداد والعشري وغير الآمن
function isIntInRange(v, min, max) {
  if (typeof v !== 'number') return false;
  if (!Number.isFinite(v)) return false;
  if (!Number.isSafeInteger(v)) return false;
  return v >= min && v <= max;
}

// نص غير فارغ بعد trim
function isNonEmptyTrimmedString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

// ---------- منطق حساب عرض السعر ----------

function computeQuote(body) {
  const items = body.items;
  const discountPercent = body.discountPercent;
  const shippingCents = body.shippingCents;

  // subtotalCents = مجموع (سعر الوحدة × الكمية)
  let subtotalCents = 0;
  for (const it of items) {
    subtotalCents += it.unitPriceCents * it.quantity;
  }
  // ضمان الحد الأقصى للمجموع قبل الخصم (مطلوب صراحة)
  if (subtotalCents > MAX_SUBTOTAL_CENTS) return null;

  // discountCents = تقريب النصف للأعلى لـ subtotalCents * discountPercent / 100
  // (الشحن لا يدخل في أساس الخصم)
  const discountCents = Math.round((subtotalCents * discountPercent) / 100);

  // totalCents = subtotal - discount + shipping
  const totalCents = subtotalCents - discountCents + shippingCents;

  return { subtotalCents, discountCents, shippingCents, totalCents };
}

// ---------- التحقق من صحة الطلب ----------

function validateQuote(body) {
  if (!isPlainObject(body)) return false;

  // items: مصفوفة من 1 إلى 100 عنصر
  if (!Array.isArray(body.items)) return false;
  if (body.items.length < 1 || body.items.length > MAX_ITEMS) return false;

  const seenSkus = new Set();
  for (const it of body.items) {
    if (!isPlainObject(it)) return false;

    // sku: نص غير فارغ بعد trim وغير مكرر
    if (!isNonEmptyTrimmedString(it.sku)) return false;
    const skuKey = it.sku.trim();
    if (seenSkus.has(skuKey)) return false;
    seenSkus.add(skuKey);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isIntInRange(it.unitPriceCents, 0, MAX_UNIT_PRICE_CENTS)) return false;

    // quantity: عدد صحيح من 1 إلى 10000
    if (!isIntInRange(it.quantity, 1, MAX_QUANTITY)) return false;
  }

  // discountPercent: عدد صحيح من 0 إلى 100
  if (!isIntInRange(body.discountPercent, 0, MAX_DISCOUNT_PERCENT)) return false;

  // shippingCents: عدد صحيح من 0 إلى 1000000
  if (!isIntInRange(body.shippingCents, 0, MAX_SHIPPING_CENTS)) return false;

  return true;
}

// ---------- قراءة الجسم وتحليل JSON ----------

function readJsonBody(req, maxBytes = 1024 * 1024) {
  return new Promise((resolve) => {
    let size = 0;
    const chunks = [];
    let done = false;

    const finish = (result) => {
      if (!done) {
        done = true;
        resolve(result);
      }
    };

    req.on('data', (chunk) => {
      if (done) return;
      size += chunk.length;
      if (size > maxBytes) {
        finish(null); // جسم كبير جدًا => غير صالح
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      if (done) return;
      const raw = Buffer.concat(chunks).toString('utf8');
      try {
        finish(JSON.parse(raw));
      } catch {
        finish(null); // JSON معطوب
      }
    });

    req.on('error', () => finish(null));
    req.on('aborted', () => finish(null));
  });
}

function sendJson(res, status, obj) {
  const payload = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
    'Cache-Control': 'no-store',
  });
  res.end(payload);
}

// ---------- خدمة الملفات الثابتة ----------

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.ico': 'image/x-icon',
};

function serveStatic(res, urlPath) {
  // GET / يخدم index.html من جذر المشروع
  let rel = urlPath === '/' ? 'index.html' : urlPath.replace(/^\/+/, '');
  const filePath = path.normalize(path.join(__dirname, rel));

  // منع الخروج من جذر المشروع (path traversal)
  if (!filePath.startsWith(__dirname + path.sep) && filePath !== __dirname) {
    sendJson(res, 404, INVALID);
    return;
  }

  fs.readFile(filePath, (err, data) => {
    if (err) {
      sendJson(res, 404, INVALID);
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME[ext] || 'application/octet-stream',
      'Content-Length': data.length,
      'Cache-Control': 'no-store',
    });
    res.end(data);
  });
}

// ---------- الخادم ----------

const server = http.createServer(async (req, res) => {
  const urlPath = (req.url || '/').split('?')[0].split('#')[0];

  if (req.method === 'GET' || req.method === 'HEAD') {
    if (urlPath === '/' || urlPath === '/index.html') {
      return serveStatic(res, '/');
    }
    return serveStatic(res, urlPath);
  }

  if (req.method === 'POST' && urlPath === '/api/quote') {
    const body = await readJsonBody(req);

    // JSON معطوب أو ليس كائنًا => 400
    if (!isPlainObject(body)) {
      return sendJson(res, 400, INVALID);
    }

    // فشل التحقق الصارم => 400
    if (!validateQuote(body)) {
      return sendJson(res, 400, INVALID);
    }

    const result = computeQuote(body);
    if (!result) {
      return sendJson(res, 400, INVALID); // تجاوز الحد الأقصى للمجموع
    }

    return sendJson(res, 200, result);
  }

  // أي مسار/طريقة أخرى
  sendJson(res, 404, INVALID);
});

server.listen(PORT, HOST, () => {
  console.log(`Quote server listening on http://localhost:${PORT}`);
});

